// TheSportsDB API Service
// Documentation: https://www.thesportsdb.com/documentation

const API_KEY = '123'; // Free API key
const BASE_URL = 'https://www.thesportsdb.com/api/v1/json';
const REAL_MADRID_TEAM_ID = 133738; // Real Madrid team ID in TheSportsDB
const LA_LIGA_LEAGUE_ID = 4335; // Spanish La Liga ID

export interface TheSportsDBEvent {
  idEvent: string;
  strEvent: string;
  strEventAlternate: string;
  strSport: string;
  idLeague: string;
  strLeague: string;
  strLeagueBadge: string;
  strSeason: string;
  strHomeTeam: string;
  strAwayTeam: string;
  intHomeScore: string | null;
  intAwayScore: string | null;
  intRound: string;
  dateEvent: string;
  strTime: string;
  strTimestamp: string;
  idHomeTeam: string;
  idAwayTeam: string;
  strHomeTeamBadge: string;
  strAwayTeamBadge: string;
  strVenue: string;
  strCountry: string;
  strStatus: string;
  strPostponed: string;
}

export interface FormattedMatch {
  id: number;
  homeTeam: string;
  awayTeam: string;
  homeScore: number | null;
  awayScore: number | null;
  homeTeamBadge: string;
  awayTeamBadge: string;
  date: string;
  time: string;
  venue: string;
  league: string;
  leagueShortCode: string;
  status: string;
  isHome: boolean;
  isCompleted: boolean;
}

/**
 * Fetch upcoming and past fixtures for Real Madrid
 */
export async function getRealMadridFixtures(
  status: 'upcoming' | 'finished' | 'all' = 'upcoming',
  limit: number = 10
): Promise<FormattedMatch[]> {
  try {
    let endpoint: string;
    
    if (status === 'finished') {
      // Get last events (results)
      endpoint = `/eventslast.php?id=${REAL_MADRID_TEAM_ID}`;
    } else {
      // Get next events (upcoming)
      endpoint = `/eventsnext.php?id=${REAL_MADRID_TEAM_ID}`;
    }
    
    const response = await fetch(
      `${BASE_URL}/${API_KEY}${endpoint}`,
      {
        headers: {
          'Accept': 'application/json',
        },
        next: { revalidate: 3600 } // Cache for 1 hour
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    
    // Handle both "events" (upcoming) and "results" (past) responses
    const events = data.events || data.results || [];
    
    if (!Array.isArray(events) || events.length === 0) {
      console.warn('No fixtures data returned from API');
      return [];
    }

    // Format and limit results
    const formatted = formatFixtures(events);
    return formatted.slice(0, limit);
  } catch (error) {
    console.error('Error fetching fixtures:', error);
    return [];
  }
}

/**
 * Fetch next upcoming match for Real Madrid
 */
export async function getNextMatch(): Promise<FormattedMatch | null> {
  try {
    const fixtures = await getRealMadridFixtures('upcoming', 1);
    return fixtures[0] || null;
  } catch (error) {
    console.error('Error fetching next match:', error);
    return null;
  }
}

/**
 * Get fixtures for La Liga (all teams)
 */
export async function getLaLigaFixtures(
  status: 'upcoming' | 'finished' = 'upcoming',
  limit: number = 10
): Promise<FormattedMatch[]> {
  try {
    const endpoint = status === 'finished' 
      ? `/eventspastleague.php?id=${LA_LIGA_LEAGUE_ID}`
      : `/eventsnextleague.php?id=${LA_LIGA_LEAGUE_ID}`;
    
    const response = await fetch(
      `${BASE_URL}/${API_KEY}${endpoint}`,
      {
        headers: {
          'Accept': 'application/json',
        },
        next: { revalidate: 3600 }
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    
    if (!data.events || !Array.isArray(data.events)) {
      return [];
    }

    const formatted = formatFixtures(data.events);
    return formatted.slice(0, limit);
  } catch (error) {
    console.error('Error fetching La Liga fixtures:', error);
    return [];
  }
}

/**
 * Format raw API data into usable match objects
 */
function formatFixtures(events: TheSportsDBEvent[]): FormattedMatch[] {
  return events.map((event): FormattedMatch => {
    // Determine if Real Madrid is playing at home
    const isHome = event.idHomeTeam === String(REAL_MADRID_TEAM_ID);
    
    // Parse scores if available
    const homeScore = event.intHomeScore ? parseInt(event.intHomeScore, 10) : null;
    const awayScore = event.intAwayScore ? parseInt(event.intAwayScore, 10) : null;
    
    // Check if match is completed
    const isCompleted = event.strStatus === 'Match Finished' || 
                        (homeScore !== null && awayScore !== null);
    
    // Format date
    const matchDate = new Date(event.dateEvent);
    const dateStr = matchDate.toLocaleDateString('en-GB', {
      weekday: 'short',
      day: 'numeric',
      month: 'short',
    });
    
    // Format time (convert from 24h format)
    const timeStr = event.strTime ? event.strTime.substring(0, 5) : 'TBD';
    
    return {
      id: parseInt(event.idEvent, 10),
      homeTeam: event.strHomeTeam,
      awayTeam: event.strAwayTeam,
      homeScore,
      awayScore,
      homeTeamBadge: event.strHomeTeamBadge || '',
      awayTeamBadge: event.strAwayTeamBadge || '',
      date: dateStr,
      time: timeStr,
      venue: event.strVenue || 'TBD',
      league: event.strLeague || 'La Liga',
      leagueShortCode: 'LaLiga',
      status: event.strStatus || (isCompleted ? 'Finished' : 'Scheduled'),
      isHome,
      isCompleted,
    };
  });
}

/**
 * Search for a team by name
 */
export async function searchTeam(teamName: string): Promise<any[]> {
  try {
    const response = await fetch(
      `${BASE_URL}/${API_KEY}/searchteams.php?t=${encodeURIComponent(teamName)}`,
      {
        headers: {
          'Accept': 'application/json',
        },
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    return data.teams || [];
  } catch (error) {
    console.error('Error searching team:', error);
    return [];
  }
}

/**
 * Get all leagues
 */
export async function getAllLeagues(): Promise<any[]> {
  try {
    const response = await fetch(
      `${BASE_URL}/${API_KEY}/all_leagues.php`,
      {
        headers: {
          'Accept': 'application/json',
        },
        next: { revalidate: 86400 } // Cache for 24 hours
      }
    );

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const data = await response.json();
    return data.leagues || [];
  } catch (error) {
    console.error('Error fetching leagues:', error);
    return [];
  }
}
